class Solution {
public:
    long long maxEnergyBoost(vector<int>& energyDrinkA, vector<int>& energyDrinkB) {
        int n = energyDrinkA.size();
        long long dpA = energyDrinkA[0];
        long long dpB = energyDrinkB[0];
        for (int i = 1; i < n; ++i) {
            long long next_dpA = max(dpA + energyDrinkA[i], dpB);
            long long next_dpB = max(dpB + energyDrinkB[i], dpA);
            dpA = next_dpA;
            dpB = next_dpB;
        }
        return max(dpA, dpB);
    }
};

class Solution {
    public long maxEnergyBoost(int[] energyDrinkA, int[] energyDrinkB) {
        int n = energyDrinkA.length;
        long dpA = energyDrinkA[0];
        long dpB = energyDrinkB[0];
        for (int i = 1; i < n; ++i) {
            long nextDpA = Math.max(dpA + energyDrinkA[i], dpB);
            long nextDpB = Math.max(dpB + energyDrinkB[i], dpA);
            dpA = nextDpA;
            dpB = nextDpB;
        }
        return Math.max(dpA, dpB);
    }
}

var maxEnergyBoost = function(energyDrinkA, energyDrinkB) {
    const n = energyDrinkA.length;
    let dpA = BigInt(energyDrinkA[0]);
    let dpB = BigInt(energyDrinkB[0]);
    for (let i = 1; i < n; i++) {
        const nextDpA = (dpA + BigInt(energyDrinkA[i]) > dpB) ? dpA + BigInt(energyDrinkA[i]) : dpB;
        const nextDpB = (dpB + BigInt(energyDrinkB[i]) > dpA) ? dpB + BigInt(energyDrinkB[i]) : dpA;
        dpA = nextDpA;
        dpB = nextDpB;
    }
    return Number(dpA > dpB ? dpA : dpB);
};
